$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$deadline = (Get-Date).AddMinutes(10)

function Get-SqlErrorNumber($exception) {
  for ($depth = 0; $depth -lt 5 -and $exception; $depth++) {
    $number = $exception.PSObject.Properties['Number']
    if ($number) { return [int]$number.Value }
    $exception = $exception.InnerException
  }
  return $null
}

function Invoke-DatabaseQuery([string]$database, [string]$query) {
  for ($attempt = 0; $attempt -lt 24; $attempt++) {
    if ((Get-Date) -ge $deadline) { throw 'SQL_BOOTSTRAP_DEADLINE_EXCEEDED' }
    try {
      $resource = 'https://' + (Get-AzContext).Environment.SqlDatabaseDnsSuffix.TrimStart('.') + '/'
      $token = (Get-AzAccessToken -ResourceUrl $resource).Token
      if ($token -is [Security.SecureString]) {
        $token = ConvertFrom-SecureString -SecureString $token -AsPlainText
      }
      return Invoke-Sqlcmd -ServerInstance $env:SQL_SERVER_FQDN -Database $database -Query $query -AccessToken $token -ConnectionTimeout 30 -QueryTimeout 60 -ErrorAction Stop
    } catch {
      $number = Get-SqlErrorNumber $_.Exception
      $retryable = $null -ne $number -and $number -in @(-2, 4060, 10928, 10929, 18456, 40197, 40501, 40613, 49918, 49919, 49920)
      if (-not $retryable -or $attempt -eq 23 -or (Get-Date) -ge $deadline) {
        throw 'SQL_BOOTSTRAP_QUERY_FAILED'
      }
      Start-Sleep -Seconds ([Math]::Min(30, [Math]::Pow(2, [Math]::Min($attempt + 1, 5))))
    }
  }
  throw 'SQL_BOOTSTRAP_RETRY_EXHAUSTED'
}

try {
  if ([string]::IsNullOrWhiteSpace($env:SQL_SERVER_FQDN) -or [string]::IsNullOrWhiteSpace($env:BACKEND_USER_NAME) -or $env:BACKEND_USER_NAME.Length -gt 128) {
    throw 'SQL_BOOTSTRAP_INVALID_INPUT'
  }
  try { $clientId = [Guid]::ParseExact($env:BACKEND_CLIENT_ID, 'D') } catch { throw 'SQL_BOOTSTRAP_INVALID_ID' }
  $databases = @($env:SQL_DATABASE_NAMES | ConvertFrom-Json)
  if ($databases.Count -eq 0) { throw 'SQL_BOOTSTRAP_INVALID_INPUT' }

  if (-not (Get-Module -ListAvailable -Name SqlServer | Where-Object Version -EQ ([Version]'22.4.5.1'))) {
    Install-Module -Name SqlServer -RequiredVersion '22.4.5.1' -Scope CurrentUser -Repository PSGallery -Force -AllowClobber -AcceptLicense
  }
  Import-Module -Name SqlServer -RequiredVersion '22.4.5.1' -ErrorAction Stop

  $sid = '0x' + [Convert]::ToHexString($clientId.ToByteArray())
  $identifier = $env:BACKEND_USER_NAME.Replace(']', ']]')
  $literal = $env:BACKEND_USER_NAME.Replace("'", "''")
  foreach ($database in $databases) {
    if ([string]::IsNullOrWhiteSpace($database) -or $database.Length -gt 128) { throw 'SQL_BOOTSTRAP_INVALID_INPUT' }
    $existing = @(Invoke-DatabaseQuery $database "SELECT CONVERT(VARCHAR(34), sid, 1) AS PrincipalSid FROM sys.database_principals WHERE name = N'$literal';")
    if ($existing.Count -gt 1) { throw 'SQL_BOOTSTRAP_IDENTITY_MISMATCH' }
    if ($existing.Count -eq 1) {
      if ($existing[0].PrincipalSid -ine $sid) { throw 'SQL_BOOTSTRAP_IDENTITY_MISMATCH' }
    } else {
      Invoke-DatabaseQuery $database "CREATE USER [$identifier] WITH SID = $sid, TYPE = E;" | Out-Null
    }
    foreach ($role in @('db_datareader', 'db_datawriter', 'db_ddladmin')) {
      Invoke-DatabaseQuery $database "IF IS_ROLEMEMBER(N'$role', N'$literal') = 0 ALTER ROLE [$role] ADD MEMBER [$identifier];" | Out-Null
    }
  }
  $DeploymentScriptOutputs = @{ completed = $true }
} catch {
  $category = $_.Exception.Message
  if ($category -notmatch '^SQL_BOOTSTRAP_[A-Z_]+$') { $category = 'SQL_BOOTSTRAP_FAILED' }
  throw $category
}

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$deadline = (Get-Date).AddMinutes(10)

function Invoke-CosmosRead([string]$path, [switch]$query) {
  for ($attempt = 0; $attempt -lt 24; $attempt++) {
    if ((Get-Date) -ge $deadline) { throw 'COSMOS_PROBE_DEADLINE_EXCEEDED' }
    try {
      $token = (Get-AzAccessToken -ResourceUrl 'https://cosmos.azure.com/').Token
      if ($token -is [Security.SecureString]) { $token = ConvertFrom-SecureString -SecureString $token -AsPlainText }
      $headers = @{
        authorization = [Uri]::EscapeDataString('type=aad&ver=1.0&sig=' + $token)
        'x-ms-date' = (Get-Date).ToUniversalTime().ToString('r', [Globalization.CultureInfo]::InvariantCulture)
        'x-ms-version' = '2018-12-31'
      }
      $request = @{
        Uri = [Uri]::new($cosmosUri, $path)
        Headers = $headers
        Method = 'Get'
        TimeoutSec = 30
        ErrorAction = 'Stop'
      }
      if ($query) {
        $headers['x-ms-documentdb-isquery'] = 'True'
        $headers['x-ms-documentdb-query-enablecrosspartition'] = 'True'
        $headers['x-ms-max-item-count'] = '1'
        $request.Method = 'Post'
        $request.ContentType = 'application/query+json'
        $request.Body = '{"query":"SELECT TOP 1 c.id FROM c","parameters":[]}'
      }
      return Invoke-RestMethod @request
    } catch {
      $status = 0
      $exception = $_.Exception
      for ($depth = 0; $depth -lt 5 -and $exception; $depth++) {
        $response = $exception.PSObject.Properties['Response']
        if ($response -and $response.Value -and $response.Value.PSObject.Properties['StatusCode']) {
          $status = [int]$response.Value.StatusCode
          break
        }
        $exception = $exception.InnerException
      }
      if ($status -notin @(0, 401, 403, 404, 408, 429, 500, 502, 503, 504) -or $attempt -eq 23 -or (Get-Date) -ge $deadline) {
        throw 'COSMOS_PROBE_REQUEST_FAILED'
      }
      Start-Sleep -Seconds ([Math]::Min(30, [Math]::Pow(2, [Math]::Min($attempt + 1, 5))))
    }
  }
  throw 'COSMOS_PROBE_RETRY_EXHAUSTED'
}

function Invoke-StorageRead([Uri]$uri, [string]$rootElement) {
  for ($attempt = 0; $attempt -lt 24; $attempt++) {
    if ((Get-Date) -ge $deadline) { throw 'STORAGE_PROBE_DEADLINE_EXCEEDED' }
    try {
      $token = (Get-AzAccessToken -ResourceUrl 'https://storage.azure.com/').Token
      if ($token -is [Security.SecureString]) { $token = ConvertFrom-SecureString -SecureString $token -AsPlainText }
      $response = Invoke-WebRequest -Uri $uri -Method Get -Headers @{
        Authorization = 'Bearer ' + $token
        'x-ms-date' = (Get-Date).ToUniversalTime().ToString('r', [Globalization.CultureInfo]::InvariantCulture)
        'x-ms-version' = '2026-10-06'
      } -TimeoutSec 30 -ErrorAction Stop
      if ($response.StatusCode -ne 200) { throw 'STORAGE_PROBE_INVALID_RESPONSE' }
      $document = [Xml.XmlDocument]::new()
      $document.XmlResolver = $null
      $settings = [Xml.XmlReaderSettings]::new()
      $settings.DtdProcessing = [Xml.DtdProcessing]::Prohibit
      $reader = [Xml.XmlReader]::Create([IO.StringReader]::new([string]$response.Content), $settings)
      try { $document.Load($reader) } finally { $reader.Dispose() }
      if ($document.DocumentElement.LocalName -ne $rootElement) { throw 'STORAGE_PROBE_INVALID_RESPONSE' }
      return
    } catch {
      $status = 0
      $exception = $_.Exception
      for ($depth = 0; $depth -lt 5 -and $exception; $depth++) {
        $responseProperty = $exception.PSObject.Properties['Response']
        if ($responseProperty -and $responseProperty.Value -and $responseProperty.Value.PSObject.Properties['StatusCode']) {
          $status = [int]$responseProperty.Value.StatusCode
          break
        }
        $exception = $exception.InnerException
      }
      if ($status -notin @(0, 401, 403, 408, 429, 500, 502, 503, 504) -or $attempt -eq 23 -or (Get-Date) -ge $deadline) {
        throw 'STORAGE_PROBE_REQUEST_FAILED'
      }
      Start-Sleep -Seconds ([Math]::Min(30, [Math]::Pow(2, [Math]::Min($attempt + 1, 5))))
    }
  }
  throw 'STORAGE_PROBE_RETRY_EXHAUSTED'
}

try {
  if ([string]::IsNullOrWhiteSpace($env:SQL_SERVER_FQDN) -or [string]::IsNullOrWhiteSpace($env:SQL_DATABASE_NAME)) {
    throw 'SQL_PROBE_INVALID_INPUT'
  }
  try { $cosmosUri = [Uri]::new($env:COSMOS_ENDPOINT, [UriKind]::Absolute) } catch { throw 'COSMOS_PROBE_INVALID_ENDPOINT' }
  if ($cosmosUri.Scheme -ne 'https' -or $cosmosUri.UserInfo -or $cosmosUri.Query -or $cosmosUri.Fragment -or $cosmosUri.AbsolutePath -ne '/') {
    throw 'COSMOS_PROBE_INVALID_ENDPOINT'
  }
  try {
    $blobUri = [Uri]::new($env:BLOB_ENDPOINT, [UriKind]::Absolute)
    $queueUri = [Uri]::new($env:QUEUE_ENDPOINT, [UriKind]::Absolute)
  } catch { throw 'STORAGE_PROBE_INVALID_ENDPOINT' }
  foreach ($uri in @($blobUri, $queueUri)) {
    if ($uri.Scheme -ne 'https' -or $uri.UserInfo -or $uri.Query -or $uri.Fragment -or $uri.AbsolutePath -ne '/') { throw 'STORAGE_PROBE_INVALID_ENDPOINT' }
  }
  if (-not (Get-Module -ListAvailable -Name SqlServer | Where-Object Version -EQ ([Version]'22.4.5.1'))) {
    Install-Module -Name SqlServer -RequiredVersion '22.4.5.1' -Scope CurrentUser -Repository PSGallery -Force -AllowClobber -AcceptLicense
  }
  Import-Module -Name SqlServer -RequiredVersion '22.4.5.1' -ErrorAction Stop
  $result = @()
  for ($attempt = 0; $attempt -lt 24; $attempt++) {
    if ((Get-Date) -ge $deadline) { throw 'SQL_PROBE_DEADLINE_EXCEEDED' }
    try {
      $resource = 'https://' + (Get-AzContext).Environment.SqlDatabaseDnsSuffix.TrimStart('.') + '/'
      $token = (Get-AzAccessToken -ResourceUrl $resource).Token
      if ($token -is [Security.SecureString]) { $token = ConvertFrom-SecureString -SecureString $token -AsPlainText }
      $query = "SELECT DB_NAME() AS DatabaseName, USER_NAME() AS CurrentUser, IS_ROLEMEMBER('db_owner') AS IsOwner, IS_ROLEMEMBER('db_datareader') AS IsReader, IS_ROLEMEMBER('db_datawriter') AS IsWriter, IS_ROLEMEMBER('db_ddladmin') AS IsDdlAdmin;"
      $result = @(Invoke-Sqlcmd -ServerInstance $env:SQL_SERVER_FQDN -Database $env:SQL_DATABASE_NAME -Query $query -AccessToken $token -ConnectionTimeout 30 -QueryTimeout 60 -ErrorAction Stop)
      break
    } catch {
      if ($attempt -eq 23 -or (Get-Date) -ge $deadline) { throw 'SQL_PROBE_CONNECTION_FAILED' }
      Start-Sleep -Seconds ([Math]::Min(30, [Math]::Pow(2, [Math]::Min($attempt + 1, 5))))
    }
  }
  if ($result.Count -ne 1 -or $result[0].DatabaseName -ne $env:SQL_DATABASE_NAME -or $result[0].CurrentUser -ne $env:BACKEND_USER_NAME -or $result[0].IsOwner -ne 0 -or $result[0].IsReader -ne 1 -or $result[0].IsWriter -ne 1 -or $result[0].IsDdlAdmin -ne 1) {
    throw 'SQL_PROBE_PERMISSIONS_FAILED'
  }
  $account = Invoke-CosmosRead ''
  if (-not $account -or -not $account.PSObject.Properties['id']) { throw 'COSMOS_PROBE_INVALID_RESPONSE' }
  foreach ($container in @('invoices', 'merchants')) {
    $path = 'dbs/primary/colls/' + $container
    $metadata = Invoke-CosmosRead $path
    if (-not $metadata -or $metadata.id -cne $container) { throw 'COSMOS_PROBE_INVALID_RESPONSE' }
    $documents = Invoke-CosmosRead ($path + '/docs') -query
    if (-not $documents -or -not $documents.PSObject.Properties['Documents']) { throw 'COSMOS_PROBE_INVALID_RESPONSE' }
  }
  Invoke-StorageRead ([Uri]::new($blobUri, 'invoices?restype=container&comp=list&maxresults=1')) 'EnumerationResults'
  Invoke-StorageRead ([Uri]::new($queueUri, 'invoice-analysis/messages?peekonly=true&numofmessages=1')) 'QueueMessagesList'
  $DeploymentScriptOutputs = @{ completed = $true }
} catch {
  $category = $_.Exception.Message
  if ($category -notmatch '^(SQL|COSMOS|STORAGE)_PROBE_[A-Z_]+$') { $category = 'BACKEND_PROBE_FAILED' }
  throw $category
}

$ErrorActionPreference = 'Stop'
$VerbosePreference = 'SilentlyContinue'
$DebugPreference = 'SilentlyContinue'
Set-StrictMode -Version Latest
$deadline = (Get-Date).AddMinutes(10)

function Get-HttpFailure($record) {
  $status = 0
  $exception = $record.Exception
  for ($depth = 0; $depth -lt 5 -and $exception; $depth++) {
    $response = $exception.PSObject.Properties['Response']
    if ($response -and $response.Value -and $response.Value.PSObject.Properties['StatusCode']) {
      $status = [int]$response.Value.StatusCode
      break
    }
    $exception = $exception.InnerException
  }
  $code = ''
  if ($record.ErrorDetails -and $record.ErrorDetails.Message) {
    try {
      $payload = ConvertFrom-Json -InputObject $record.ErrorDetails.Message -AsHashtable
      if ($payload.ContainsKey('error') -and $payload.error -is [Collections.IDictionary]) {
        if ($payload.error.ContainsKey('code')) { $code = [string]$payload.error.code }
        if ($payload.error.ContainsKey('innererror') -and $payload.error.innererror.ContainsKey('code')) {
          $code = [string]$payload.error.innererror.code
        }
      }
    } catch { $code = '' }
  }
  return @{status=$status;code=$code}
}

function Invoke-ConfigurationRequest([Uri]$uri, [string]$method, [string]$body = '', [switch]$allowMissing) {
  for ($attempt = 0; $attempt -lt 24; $attempt++) {
    if ((Get-Date) -ge $deadline) { throw 'CONFIG_BOOTSTRAP_DEADLINE_EXCEEDED' }
    try {
      $isVault = $uri.Host -eq $vaultUri.Host
      if (-not $isVault -and $uri.Host -ne $storeUri.Host) { throw 'CONFIG_BOOTSTRAP_INVALID_TARGET' }
      $audience = if ($isVault) { (Get-AzContext).Environment.AzureKeyVaultServiceEndpointResourceId.TrimEnd('/') } else { 'https://azconfig.io' }
      $token = (Get-AzAccessToken -ResourceUrl $audience).Token
      if ($token -is [Security.SecureString]) { $token = ConvertFrom-SecureString -SecureString $token -AsPlainText }
      $request = @{
        Uri = $uri
        Method = $method
        Headers = @{Authorization='Bearer ' + $token}
        TimeoutSec = 30
        ErrorAction = 'Stop'
      }
      if ($method -eq 'Put') {
        $request.Body = $body
        $request.ContentType = if ($isVault) { 'application/json' } else { 'application/vnd.microsoft.appconfig.kv+json' }
      }
      return Invoke-RestMethod @request
    } catch {
      $failure = Get-HttpFailure $_
      if ($allowMissing -and $method -eq 'Get' -and $uri.Host -eq $vaultUri.Host -and $uri.AbsolutePath.StartsWith('/secrets/') -and $failure.status -eq 404) {
        return $null
      }
      $propagation = $failure.status -eq 403 -and $failure.code -in @('ForbiddenByRbac', 'RoleAssignmentNotPropagated')
      $retryable = $propagation -or $failure.status -in @(408, 429, 500, 502, 503, 504)
      if (-not $retryable -or $attempt -eq 23 -or (Get-Date) -ge $deadline) { throw 'CONFIG_BOOTSTRAP_REQUEST_FAILED' }
      Start-Sleep -Seconds ([Math]::Min(30, [Math]::Pow(2, [Math]::Min($attempt + 1, 5))))
    }
  }
  throw 'CONFIG_BOOTSTRAP_RETRY_EXHAUSTED'
}

function Get-Secret([string]$name) {
  $path = 'secrets/' + [Uri]::EscapeDataString($name) + '?api-version=2025-07-01'
  return Invoke-ConfigurationRequest ([Uri]::new($vaultUri, $path)) 'Get' -allowMissing
}

function Set-Secret([string]$name, [string]$value) {
  $path = 'secrets/' + [Uri]::EscapeDataString($name) + '?api-version=2025-07-01'
  $body = ConvertTo-Json -Depth 10 -Compress -InputObject @{value=$value;attributes=@{enabled=$true}}
  Invoke-ConfigurationRequest ([Uri]::new($vaultUri, $path)) 'Put' $body | Out-Null
}

function Set-Configuration([string]$key, [string]$label, [string]$value, [string]$contentType = '', [hashtable]$tags = @{}) {
  $disabledEmail = $key -eq 'Communication:Email:ApiKey' -and $value -ceq '' -and $contentType -eq ''
  if ([string]::IsNullOrWhiteSpace($key) -or $label -notin @('DEVELOPMENT','PRODUCTION') -or ([string]::IsNullOrWhiteSpace($value) -and -not $disabledEmail)) {
    throw 'CONFIG_BOOTSTRAP_INVALID_SETTING'
  }
  $path = 'kv/' + [Uri]::EscapeDataString($key) + '?label=' + [Uri]::EscapeDataString($label) + '&api-version=2026-04-01'
  $body = ConvertTo-Json -Depth 10 -Compress -InputObject @{key=$key;label=$label;value=$value;content_type=$contentType;tags=$tags}
  Invoke-ConfigurationRequest ([Uri]::new($storeUri, $path)) 'Put' $body | Out-Null
}

try {
  try {
    $vaultUri = [Uri]::new($env:KEY_VAULT_URI.TrimEnd('/') + '/', [UriKind]::Absolute)
    $storeUri = [Uri]::new($env:APP_CONFIGURATION_ENDPOINT.TrimEnd('/') + '/', [UriKind]::Absolute)
    $manifest = ConvertFrom-Json -InputObject $env:CONFIGURATION_MANIFEST -AsHashtable
  } catch { throw 'CONFIG_BOOTSTRAP_INVALID_INPUT' }
  foreach ($uri in @($vaultUri, $storeUri)) {
    if ($uri.Scheme -ne 'https' -or $uri.UserInfo -or $uri.Query -or $uri.Fragment -or $uri.AbsolutePath -ne '/') { throw 'CONFIG_BOOTSTRAP_INVALID_ENDPOINT' }
  }
  if ([string]::IsNullOrWhiteSpace($env:COGNITIVE_SERVICES_KEY) -or $manifest.labels.Count -ne 2 -or 'DEVELOPMENT' -notin $manifest.labels -or 'PRODUCTION' -notin $manifest.labels) {
    throw 'CONFIG_BOOTSTRAP_INVALID_INPUT'
  }

  $pending = [Collections.Generic.List[string]]::new()
  $jwtName = ($manifest.references | Where-Object key -EQ 'Auth:JWT:Secret').name
  $jwt = Get-Secret $jwtName
  if ($null -eq $jwt -or $jwt.value -in @('<your-jwt-secret>', '<replace-with-jwt-secret>')) {
    $generated = [Convert]::ToBase64String([Security.Cryptography.RandomNumberGenerator]::GetBytes(64))
    Set-Secret $jwtName $generated
  } elseif ($jwt.value -isnot [string] -or [string]::IsNullOrWhiteSpace($jwt.value) -or [Text.Encoding]::UTF8.GetByteCount($jwt.value) -lt 32) {
    throw 'CONFIG_BOOTSTRAP_INVALID_EXISTING_JWT'
  }

  foreach ($label in $manifest.labels) {
    $aiName = $label + '-CognitiveServicesKey'
    $ai = Get-Secret $aiName
    if ($null -eq $ai -or $ai.value -cne $env:COGNITIVE_SERVICES_KEY) { Set-Secret $aiName $env:COGNITIVE_SERVICES_KEY }
    foreach ($reference in $manifest.references) {
      $name = if ($reference.owner -eq 'internal') { $reference.name } else { $label + '-' + $reference.name }
      if ($reference.owner -eq 'external') {
        $external = Get-Secret $name
        if ($null -eq $external -or [string]::IsNullOrWhiteSpace($external.value) -or $external.value -match '^<(your|replace-with)-[a-z-]+>$') {
          $pending.Add($name)
          if ($reference.ContainsKey('optional') -and $reference.optional) {
            Set-Configuration $reference.key $label ''
            continue
          }
        }
      }
      $value = ConvertTo-Json -Compress -InputObject @{uri=[Uri]::new($vaultUri, 'secrets/' + [Uri]::EscapeDataString($name)).AbsoluteUri}
      Set-Configuration $reference.key $label $value 'application/vnd.microsoft.appconfig.keyvaultref+json;charset=utf-8'
    }
    foreach ($setting in $manifest.settings) { Set-Configuration $setting.key $label $setting.value }
  }
  foreach ($setting in $manifest.defaults) { Set-Configuration $setting.key $setting.label $setting.value $setting.content_type $setting.tags }
  $DeploymentScriptOutputs = @{completed=$true;pendingExternalSecretNames=@($pending.ToArray())}
} catch {
  $category = $_.Exception.Message
  if ($category -notmatch '^CONFIG_BOOTSTRAP_[A-Z_]+$') { $category = 'CONFIG_BOOTSTRAP_FAILED' }
  throw $category
}

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$deadline = (Get-Date).AddMinutes(15)
$types = @{A=1;NS=2;CNAME=5;TXT=16;DS=43}

function Normalize-DnsValue([string]$value, [string]$type) {
  $value = $value.Trim()
  if ($type -in @('NS','CNAME')) { return $value.TrimEnd('.').ToLowerInvariant() }
  if ($type -eq 'TXT') { return $value.Trim('"') }
  if ($type -eq 'DS') { return ($value -replace '\s+', ' ').ToUpperInvariant() }
  return $value
}

function Get-PublicDns([string]$name, [string]$type) {
  if ((Get-Date) -ge $deadline) { throw 'DNS_NOT_READY' }
  $uri = 'https://cloudflare-dns.com/dns-query?name=' + [Uri]::EscapeDataString($name) + '&type=' + [Uri]::EscapeDataString($type) + '&cd=false'
  try {
    $reply = Invoke-RestMethod -Uri $uri -Method Get -Headers @{Accept='application/dns-json'} -TimeoutSec 10 -ErrorAction Stop
  } catch { throw 'DNS_RESOLVER_UNAVAILABLE' }
  if (-not $reply -or -not $reply.PSObject.Properties['Status'] -or ($reply.Status -isnot [int] -and $reply.Status -isnot [long]) -or $reply.Status -lt 0 -or $reply.Status -gt 15) {
    throw 'DNS_RESOLVER_UNAVAILABLE'
  }
  if ($reply.Status -ne 0) { return @() }
  if (-not $reply.PSObject.Properties['Answer']) { return @() }
  if ($reply.Answer -isnot [Array]) { throw 'DNS_RESOLVER_UNAVAILABLE' }
  $values = [Collections.Generic.List[string]]::new()
  foreach ($answer in $reply.Answer) {
    if (-not $answer.PSObject.Properties['type'] -or -not $answer.PSObject.Properties['data'] -or ($answer.type -isnot [int] -and $answer.type -isnot [long]) -or $answer.data -isnot [string] -or [string]::IsNullOrWhiteSpace($answer.data)) {
      throw 'DNS_RESOLVER_UNAVAILABLE'
    }
    if ($answer.type -eq $types[$type]) {
      if ($type -eq 'A') {
        $address = $null
        if (-not [Net.IPAddress]::TryParse($answer.data, [ref]$address) -or $address.AddressFamily -ne [Net.Sockets.AddressFamily]::InterNetwork) {
          throw 'DNS_RESOLVER_UNAVAILABLE'
        }
      }
      $values.Add((Normalize-DnsValue $answer.data $type))
    }
  }
  return @($values.ToArray())
}

try {
  try { $manifest = ConvertFrom-Json -InputObject $env:DNS_EXPECTATIONS -AsHashtable } catch { throw 'DNS_INVALID_INPUT' }
  $zoneName = Normalize-DnsValue $manifest.zoneName 'NS'
  if ($zoneName -notmatch '^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z0-9-]+$' -or $manifest.authoritativeNameServers.Count -eq 0 -or $manifest.records.Count -eq 0) {
    throw 'DNS_INVALID_INPUT'
  }
  $expectedNs = @($manifest.authoritativeNameServers | ForEach-Object { Normalize-DnsValue $_ 'NS' } | Sort-Object -Unique)
  $hasDs = $false
  foreach ($record in $manifest.records) {
    $name = Normalize-DnsValue $record.name 'NS'
    if (($name -ne $zoneName -and -not $name.EndsWith('.' + $zoneName)) -or $record.type -notin @('A','CNAME','TXT','DS')) { throw 'DNS_INVALID_INPUT' }
    if ($record.expectedValues.Count -eq 0 -and -not ($record.type -eq 'A' -and $name -eq $zoneName)) { throw 'DNS_INVALID_INPUT' }
    if ($record.type -eq 'DS' -and $name -eq $zoneName -and $record.expectedValues.Count -gt 0) { $hasDs = $true }
  }
  if (-not $hasDs) { throw 'DNS_INVALID_INPUT' }

  $failure = 'DNS_NOT_READY'
  $verified = $false
  for ($attempt = 0; $attempt -lt 32 -and (Get-Date) -lt $deadline; $attempt++) {
    try {
      $actualNs = @(Get-PublicDns $zoneName 'NS' | Sort-Object -Unique)
      $ready = ($actualNs -join '|') -ceq ($expectedNs -join '|')
      foreach ($record in $manifest.records) {
        if (-not $ready) { break }
        $actual = @(Get-PublicDns $record.name $record.type)
        $expected = @($record.expectedValues | ForEach-Object { Normalize-DnsValue $_ $record.type })
        if ($record.type -eq 'DS') {
          $ready = @($expected | Where-Object { $_ -cin $actual }).Count -gt 0
        } elseif ($expected.Count -eq 0) {
          $ready = $actual.Count -gt 0
        } else {
          $ready = @($expected | Where-Object { $_ -cnotin $actual }).Count -eq 0
        }
      }
      if ($ready) { $verified = $true; break }
      $failure = 'DNS_NOT_READY'
    } catch {
      $failure = if ($_.Exception.Message -eq 'DNS_RESOLVER_UNAVAILABLE') { 'DNS_RESOLVER_UNAVAILABLE' } else { 'DNS_NOT_READY' }
    }
    if ($attempt -lt 31 -and (Get-Date) -lt $deadline) {
      $remaining = [Math]::Max(0, [Math]::Floor(($deadline - (Get-Date)).TotalSeconds))
      $delay = [Math]::Min($remaining, [Math]::Min(30, [Math]::Pow(2, [Math]::Min($attempt + 1, 5))))
      if ($delay -gt 0) { Start-Sleep -Seconds $delay }
    }
  }
  if (-not $verified) { throw $failure }
  $DeploymentScriptOutputs = @{completed=$true}
} catch {
  $category = $_.Exception.Message
  if ($category -notin @('DNS_NOT_READY','DNS_RESOLVER_UNAVAILABLE','DNS_INVALID_INPUT')) { $category = 'DNS_INVALID_INPUT' }
  throw $category
}
